import React, { useState, useEffect, useCallback, useRef } from 'react';
import { MapContainer, TileLayer, useMap } from 'react-leaflet';
import { Play, Pause, FastForward, Zap, Truck, Activity, MessageSquare, LayoutDashboard, AlertTriangle, Shield, MapPin } from 'lucide-react';
import { clsx } from 'clsx';

import DisasterLayer from './components/DisasterLayer';
import AgentMarkers from './components/AgentMarkers';
import InfrastructureLayer from './components/InfrastructureLayer';
import NegotiationLines from './components/NegotiationLines';
import TimelinePanel from './components/TimelinePanel';
import AgentDetailPanel from './components/AgentDetailPanel';
import GlobalDashboard from './components/GlobalDashboard';
import CollaborationGraph from './components/CollaborationGraph';
import { useWebSocket } from './services/websocket';

// 生成模拟数据（在 WebSocket 未连接时使用）
const generateMockData = (tick) => ({
  tick,
  worldState: {
    zones: [
      { id: 'zone_01', disasterIntensity: 0.1, trapped: 2, casualties: 1, roadAvailable: true },
      { id: 'zone_02', disasterIntensity: 0.3, trapped: 5, casualties: 3, roadAvailable: true },
      { id: 'zone_03', disasterIntensity: 0.6, trapped: 12, casualties: 8, roadAvailable: false },
      { id: 'zone_04', disasterIntensity: 0.9, trapped: 25, casualties: 15, roadAvailable: false },
      { id: 'zone_05', disasterIntensity: 0.7, trapped: 18, casualties: 12, roadAvailable: true },
      { id: 'zone_06', disasterIntensity: 0.2, trapped: 3, casualties: 1, roadAvailable: true },
      { id: 'zone_07', disasterIntensity: 0.0, trapped: 0, casualties: 0, roadAvailable: true },
      { id: 'zone_08', disasterIntensity: 0.1, trapped: 1, casualties: 0, roadAvailable: true },
      { id: 'zone_09', disasterIntensity: 0.0, trapped: 0, casualties: 0, roadAvailable: true },
    ],
    eocPriorities: {
      'zone_03': 0.7,
      'zone_04': 0.95,
      'zone_05': 0.8
    }
  },
  agents: [
    {
      id: 'eoc',
      role: 'eoc',
      position: { lat: 39.9042, lng: 116.4074 },
      currentTask: '协调全局救援',
      resources: {},
      lastDecision: { action: 'direct', reason: '优先救援 zone_04' },
      thinking: '分析当前灾害分布，zone_04 灾害强度最高，受困人数最多，需要优先调度消防和医疗资源...'
    },
    {
      id: 'fire_1',
      role: 'fire',
      position: { lat: 39.9082, lng: 116.4124 },
      currentTask: '前往 zone_04 灭火',
      resources: { water: 80, pumps: 2 },
      lastDecision: { action: 'moveTo', target: 'zone_04', reason: 'zone_04 火灾严重' },
      thinking: '检测到 zone_04 灾害强度 0.9，我的水量充足，决定前往支援...'
