      position: { lat: 39.9012, lng: 116.4024 },
      currentTask: '在 zone_03 治疗伤员',
      resources: { medkits: 45, ambulances: 3 },
      lastDecision: { action: 'treat', reason: 'zone_03 有大量伤员' },
      thinking: '当前有 12 人受困，药品即将耗尽，需要联系物流请求补给...'
    },
    {
