      role: 'logistics',
      position: { lat: 39.9062, lng: 116.3994 },
      currentTask: '向 zone_03 运送药品',
      resources: { food: 200, medkits: 80, coldTrucks: 2 },
      lastDecision: { action: 'deliver', target: 'zone_03', reason: '医疗队请求支援' },
      thinking: '收到医疗的协商请求，同意用 10 箱药品交换优先配送权...'
    },
    {
      id: 'public_info',
      role: 'public_info',
      position: { lat: 39.9032, lng: 116.4104 },
      currentTask: '发布避险公告',
      resources: {},
      lastDecision: { action: 'announce', reason: '需要提醒市民撤离' },
      thinking: '根据社交媒体分析，市民对 zone_05 情况担忧，发布预警公告...'
    }
  ],
  events: [
    { id: 1, time: '12:30', type: 'eoc', message: 'EOC 发布指令：优先疏散 zone_04', tick: tick - 5 },
    { id: 2, time: '12:31', type: 'resource', message: '消防队报告：剩余水量 80%', tick: tick - 4 },
    { id: 3, time: '12:32', type: 'negotiation', message: '医疗 ↔ 物流：达成药品运输协议', tick: tick - 3 },
    { id: 4, time: '12:33', type: 'public', message: '公宣队发布全市预警：撤离低洼地区', tick: tick - 2 },
    { id: 5, time: '12:34', type: 'collision', message: '救援冲突：两支队伍争抢同一条道路', tick: tick - 1 },
  ],
